<?php
require_once __DIR__ . '/../config/db.php';require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../services/userService.php';$pdo=openDatabase();$actor=requireLogin($pdo);requireRole($actor,['Administrator']);$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Invalid user');}$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{$action=(string)($_POST['action']??'');if($action==='role'){changeUserRole($pdo,$actor,$id,(string)($_POST['role']??''));}elseif($action==='status'){changeUserStatus($pdo,$actor,$id,(string)($_POST['status']??''));}elseif($action==='delete'){removeUser($pdo,$actor,$id);header('Location: manage-users.php?deleted=1',true,303);exit;}else{throw new InvalidArgumentException('Invalid action.');}$message='User updated.';}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
$target=findUserById($pdo,$id);if(!$target){http_response_code(404);exit('User not found');}require __DIR__ . '/../includes/header.php';require __DIR__ . '/../includes/nav.php'; ?>
<main class="container py-4"><h1>Manage account</h1><?php if($message):?><div class="alert alert-success"><?=$message?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><dl><dt>Name</dt><dd><?=htmlspecialchars($target['full_name'],ENT_QUOTES,'UTF-8')?></dd><dt>Email</dt><dd><?=htmlspecialchars($target['email'],ENT_QUOTES,'UTF-8')?></dd><dt>Role</dt><dd><?=$target['role']?></dd><dt>Status</dt><dd><?=$target['status']?></dd></dl><form method="post" class="mb-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="action" value="role"><label>Role <select name="role"><?php foreach(userRoles() as $r):?><option <?=$r===$target['role']?'selected':''?>><?=$r?></option><?php endforeach;?></select></label><button class="btn btn-primary">Save role</button></form><form method="post" class="mb-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="action" value="status"><label>Status <select name="status"><?php foreach(userStatuses() as $s):?><option <?=$s===$target['status']?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><button class="btn btn-warning">Update status</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger" onclick="return confirm('Delete this account? Related tutoring requests block deletion.')">Delete account</button></form></main><?php require __DIR__ . '/../includes/footer.php'; ?>
